cat <<'EOF' > app/javascript/helpers/date_helpers.js
const DAY_IN_MILLISECONDS = 1000 * 60 * 60 * 24
const formatterCache = new Map()

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / DAY_IN_MILLISECONDS)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInLocalTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

export function formatDateTime(date, format, now = new Date()) {
  switch (format) {
    case "time":
      return formatTime(date)
    case "relative":
      return formatRelative(date, now)
    case "relative-future":
      return formatRelativeFuture(date, now)
    case "short-date":
    case "date":
      return formatShortDate(date)
    case "long-date":
      return formatLongDate(date)
    case "weekday-date":
      return formatWeekdayDate(date)
    case "date-time":
      return formatDateAndTime(date)
    default:
      return formatShortDate(date)
  }
}

export function formatTime(date) {
  return format(date, {
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  })
}

export function formatRelative(date, now = new Date()) {
  const daysAgo = signedDifferenceInDays(date, now)

  if (daysAgo === 0) {
    return formatTime(date)
  } else if (daysAgo === 1) {
    return "yesterday"
  } else if (daysAgo > 1 && daysAgo < 7) {
    return `${daysAgo} days ago`
  } else if (daysAgo < 0) {
    const daysUntil = Math.abs(daysAgo)
    if (daysUntil === 1) {
      return "tomorrow"
    } else if (daysUntil < 7) {
      return `in ${daysUntil} days`
    }
  }

  return formatShortDate(date, now)
}

export function formatRelativeFuture(date, now = new Date()) {
  const daysUntil = signedDifferenceInDays(now, date)

  if (daysUntil === 0) {
    return "today"
  } else if (daysUntil === 1) {
    return "tomorrow"
  } else if (daysUntil > 1 && daysUntil < 7) {
    return `in ${daysUntil} days`
  } else if (daysUntil < 0) {
    return formatRelative(date, now)
  }

  return formatShortDate(date, now)
}

function formatShortDate(date, referenceDate = new Date()) {
  const options = { month: "short", day: "numeric" }

  if (date.getFullYear() !== referenceDate.getFullYear()) {
    options.year = "numeric"
  }

  return format(date, options)
}

function formatLongDate(date) {
  return format(date, { month: "short", day: "numeric", year: "numeric" })
}

function formatWeekdayDate(date) {
  return format(date, { weekday: "long", month: "long", day: "numeric" })
}

function formatDateAndTime(date) {
  return format(date, {
    month: "numeric",
    day: "numeric",
    year: "2-digit",
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  })
}

function format(date, options) {
  const key = JSON.stringify(options)
  let formatter = formatterCache.get(key)

  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-US", options)
    formatterCache.set(key, formatter)
  }

  return formatter.format(date)
}

function datePartsInLocalTimezone(date) {
  return localDateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

function localDateFormatter() {
  const options = { year: "numeric", month: "2-digit", day: "2-digit" }
  const key = JSON.stringify(options)
  let formatter = formatterCache.get(key)

  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-US", options)
    formatterCache.set(key, formatter)
  }

  return formatter
}
